package cpamp

import (
	"context"
	"encoding/json"
	"strings"
)

// Page the request ledger at the same immutable checkpoint as the aggregates.
// A page turn reads 25 payloads instead of decoding/repricing the entire ledger
// and recalculating every historical quota window.
func (s *Service) workspaceRequests(ctx context.Context, r ProfileWorkspaceReport, page int) ([]WorkspaceRequest, error) {
	f := r.Filter
	where := []string{"a.event_id<=?"}
	args := []any{f.Through}
	for _, item := range []struct {
		clause  string
		value   any
		include bool
	}{
		{"a.started_ms>=?", f.From, f.From > 0},
		{"a.started_ms<?", f.To, f.To > 0},
		{"a.account=?", f.Account, f.Account != ""},
		{"json_extract(a.payload,'$.model')=?", f.Model, f.Model != ""},
	} {
		if item.include {
			where = append(where, item.clause)
			args = append(args, item.value)
		}
	}
	if f.APIKey != "" {
		keys := apiKeyHashes(f.APIKey)
		placeholders := make([]string, len(keys))
		for i, key := range keys {
			placeholders[i] = "?"
			args = append(args, key)
		}
		where = append(where, keyValue+" IN ("+strings.Join(placeholders, ",")+")")
	}
	if f.Profile != "" {
		periods := []string{}
		for _, p := range r.Config.Profiles {
			if f.Profile != "all" && f.Profile != "unassigned" && p.ID != f.Profile {
				continue
			}
			for _, m := range profileMemberships(r.Config, p) {
				periods = append(periods, "(a.account=? AND a.started_ms>=? AND (?=0 OR a.started_ms<?))")
				args = append(args, m.Account, m.Start, m.End, m.End)
			}
		}
		clause := "0"
		if len(periods) > 0 {
			clause = strings.Join(periods, " OR ")
		}
		if f.Profile == "unassigned" {
			clause = "NOT (" + clause + ")"
		}
		where = append(where, "("+clause+")")
	}
	args = append(args, r.PageSize, page*r.PageSize)
	pageJoins := ""
	if f.APIKey != "" {
		pageJoins = keyJoins
	}
	query := "WITH page AS (SELECT a.event_hash FROM analytics_events a " + pageJoins + " WHERE " + strings.Join(where, " AND ") + " ORDER BY a.started_ms DESC,a.event_hash LIMIT ? OFFSET ?) SELECT a.payload," + keyValue + " FROM page p JOIN analytics_events a ON a.event_hash=p.event_hash " + keyJoins + " ORDER BY a.started_ms DESC,a.event_hash"
	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	events := []Event{}
	for rows.Next() {
		var raw, key string
		var e Event
		if err = rows.Scan(&raw, &key); err == nil {
			err = json.Unmarshal([]byte(raw), &e)
		}
		if err != nil {
			rows.Close()
			return nil, err
		}
		e.APIKeyHash = key
		events = append(events, e)
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return nil, err
	}
	if err = s.correctEventAccounting(ctx, events); err != nil {
		return nil, err
	}

	groups := map[string][]Event{}
	for _, e := range events {
		groups[e.Account] = append(groups[e.Account], e)
	}
	enriched := map[string]*TokenEvidence{}
	for _, group := range groups {
		if err = s.enrichTokenEvidence(ctx, group, r.PriceBook, f.TokenEvidenceThrough); err != nil {
			return nil, err
		}
		for _, e := range group {
			enriched[e.Hash] = e.TokenEvidence
		}
	}
	for i := range events {
		events[i].TokenEvidence = enriched[events[i].Hash]
	}
	valueEvents(events, r.PriceBook)
	out := []WorkspaceRequest{}
	for _, e := range events {
		out = append(out, WorkspaceRequest{TokenEvidence: e.TokenEvidence, Value: e.Value, Hash: e.Hash, Account: e.Account, Label: e.Label, Model: e.Model, Started: e.Started, Tokens: e.Tokens, CostNano: e.CostNano, Failed: e.Failed})
	}
	return out, nil
}
